## Printed-layout transcription from the source PDF, 2026-11-20; AI check, human signoff pending.
.sp<-local({f<-tryCatch(sys.frame(1)$ofile,error=function(e)NULL);if(!is.null(f))f else sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)[1])})
folder<-dirname(normalizePath(.sp,mustWork=TRUE));item_name<-sub('_snapshot$','',tools::file_path_sans_ext(basename(.sp)))
source_text <- "Table 1. Volumes of the different ROIs based on high-resolution anatomical MRI. N = 10 rats per group. Data represents mean ± SEM in μl and was analyzed using 2-way ANOVA with MD and mifepristone treatment as main factors. Statistical significance based on p-values for the main effect is presented in the last three columns: * p < 0.05, ** p < 0.01, ns = not significant.\t\t\t\t\t\t\t\n\tVehicle\t\tMifepristone\t\tMD\tTreatment\tInteraction\nVolume (μl)\tNo MD\tMD\tNo MD\tMD\t\t\t\nCerebrum\t1550.5 ± 10.0\t1546.6 ± 11.9\t1573.8 ± 16.1\t1548.9 ± 15.7\tns\tns\tns\nCorpus Callosum\t30.4 ± 2.2\t31.3 ± 2.4\t31.0 ± 2.2\t30.5 ± 3.0\tns\tns\tns\nLateral Ventricles\t40.1 ± 1.8\t38.6 ± 0.7\t39.6 ± 1.1\t38.9 ± 1.3\tns\tns\tns\nHippocampus\t91.0 ± 1.1\t91.4 ± 0.7\t91.3 ± 1.2\t90.6 ± 1.4\tns\tns\tns\nAmygdala\t29.2 ± 0.3\t29.1 ± 0.3\t29.4 ± 0.3\t29.6 ± 0.5\tns\tns\tns\ndmStriatum\t16.8 ± 0.2\t17.0 ± 0.3\t17.6 ± 0.5\t16.6 ± 0.3\tns\tns\tns\nPFC\t101.7 ± 0.4\t99.6 ± 0.3\t101.4 ± 1.0\t98.9 ± 1.1\t**\tns\tns\nOFC\t22.9 ± 0.2\t22.1 ± 0.1\t22.4 ± 0.3\t22.2 ± 0.2\t*\tns\tns\nmPFC\t14.4 ± 0.3\t13.6 ± 0.2\t14.1 ± 0.2\t13.1 ± 0.3\t**\tns\tns\nInsular cortex\t48.9 ± 0.3\t48.5 ± 0.5\t49.2 ± 0.7\t48.9 ± 0.4\tns\tns\tns\nMean ± SEM; source caption retained in first row.\t\t\t\t\t\t\t"
d<-read.delim(text=source_text,header=FALSE,sep='\t',quote='',fill=TRUE,colClasses='character',check.names=FALSE,blank.lines.skip=FALSE)
p<-file.path(folder,paste0(item_name,'_snapshot.csv'));tmp<-tempfile(fileext='.csv');write.table(d,tmp,sep=',',row.names=FALSE,col.names=FALSE,na='',fileEncoding='UTF-8',qmethod='double')
if(file.exists(p)){if(!identical(readBin(p,'raw',n=file.info(p)$size),readBin(tmp,'raw',n=file.info(tmp)$size)))stop('Frozen snapshot differs; refusing overwrite.')}else file.copy(tmp,p)
unlink(tmp)
